# --- check helper (src/lib/codeRunner/checkHelpers.js) ---
dwf_escape() {
	local text=$1 format=$2 code hex char escaped
	text=${text//'\'/'\\'}
	text=${text//'"'/'\"'}
	text=${text//$'\n'/'\n'}
	text=${text//$'\r'/'\r'}
	text=${text//$'\t'/'\t'}
	if [[ $text == *[[:cntrl:]]* ]]; then
		for (( code = 1; code < 32; code++ )); do
			printf -v hex '%02x' "$code"
			printf -v char "\\x$hex"
			printf -v escaped "$format" "$code"
			text=${text//"$char"/"$escaped"}
		done
	fi
	DWF_ESCAPED=$text
}

dwf_json() {
	dwf_escape "$1" '\\u%04x'
	printf '"%s"' "$DWF_ESCAPED"
}

dwf_show() {
	dwf_escape "$1" '\\x%02x'
	local text="\"$DWF_ESCAPED\""
	if (( ${#text} > 300 )); then
		text="${text:0:300}…"
	fi
	printf '%s' "$text"
}

check() {
	local name=$1 got=$2 expected=$3 pass=false
	if [[ "$got" == "$expected" ]]; then
		pass=true
	fi
	printf '@@check@@ {"name":%s,"pass":%s,"got":%s,"expected":%s}\n' \
		"$(dwf_json "$name")" "$pass" "$(dwf_json "$(dwf_show "$got")")" "$(dwf_json "$(dwf_show "$expected")")"
	return 0
}

dwf_check_done() {
	printf '%s\n' '@@check@@ {"done":true}'
}
# --- end of the check helper ---
check "count" "$(count)" 0
dwf_check_done
